import hdr_emptyWarehouse01 from '../../img/hdr/empty_warehouse_01_1k.hdr'

import { Canvas } from '@react-three/fiber'
import { Environment, OrbitControls, Float } from '@react-three/drei'
import { Model as DefaultModel } from '../../models/Default'

const LatestWorkTVSection = () =>
{
    return <div className="PageSection-module--root fillScreen">
        <Canvas className="CanvasSetup-module">
            <Environment files={hdr_emptyWarehouse01} />
            <OrbitControls
                autoRotateSpeed={1}
                enableZoom={false}
                autoRotate={true} />
            <directionalLight
                intensity={3}
                position={[-0.25, 0, 1]} 
                castShadow />
            <Float>
                <DefaultModel rotation={[0.5, 1, 0]} />
            </Float>
        </Canvas>
    </div>
}

export default LatestWorkTVSection